/**
 * The GPU profile: a developer diagnostic, opened with `?gpu-profile`, that
 * says how many milliseconds of graphics-card time each of a planet's
 * effects costs a frame. An overlay waits for the world, runs the sweep
 * (src/debug/gpuProfileSweep.ts) with the camera held still, and shows a
 * table it can copy as plain text; the same text goes to the console.
 *
 * How a frame is timed, best first:
 * - WebGPU with the `timestamp-query` feature (the engine asks for it under
 *   the flag): every render and compute pass gets timestamp writes, and a
 *   frame's time is the sum of its passes', so each pass is timed too and
 *   named for its render target (the main pass, the shadow map, the depth
 *   map, the post-processes). Babylon's own WebGPU frame timer needs
 *   `GPUCommandEncoder.writeTimestamp`, which Chrome does not ship, so this
 *   does not use it. Chrome rounds timestamps unless its "WebGPU Developer
 *   Features" flag is on; the readout says when they look rounded.
 * - WebGL2 with EXT_disjoint_timer_query_webgl2: a timer query around
 *   each whole frame, no passes.
 * - Otherwise the CPU frame interval, which is bounded by the display's
 *   rate and is not GPU time; the readout says so.
 *
 * Code-split: main.ts imports this only under the flag. It gives the world
 * nothing and reads only what the shell already has.
 */

import type { AbstractEngine } from '@babylonjs/core/Engines/abstractEngine';
import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { Scene } from '@babylonjs/core/scene';
import type { Observer } from '@babylonjs/core/Misc/observable';
import type { ClientHints } from '../hints/clientHints';
import type { HintName } from '../veml/clientHintsVocabulary';
import { SWEEP_STEPS, formatReadout, hintsBefore, hintsNotGivenBack, runSweep, summarise, type ReadoutInfo, type StepSample, type TimerKind } from './gpuProfileSweep';

/** How long after the world has entered the sweep starts by itself, so its tiles and chunks have come. */
export const AUTO_START_MS = 20_000;
/** And how long the scene's mesh count must have held still. */
export const MESHES_STILL_MS = 10_000;
/** The longest it waits for that before it starts anyway. */
export const AUTO_START_LIMIT_MS = 60_000;

export interface GpuProfileOptions {
  engine: AbstractEngine;
  kind: string;
  hints: () => ClientHints;
  scene: () => Scene;
  worldEntered: () => boolean;
  tier: () => string;
  renderScale: () => number;
}

interface FrameTimer {
  kind: TimerKind;
  /** What the reader should know about this timer's numbers, read after a sweep. */
  note(): string;
  start(): void;
  stop(): StepSample;
  dispose(): void;
}

// --- WebGPU: timestamps on every pass -----------------------------------

// The few WebGPU shapes used here, written out so the shell needs no WebGPU type package.
interface GpuBufferLike {
  mapAsync(mode: number): Promise<void>;
  getMappedRange(offset?: number, size?: number): ArrayBuffer;
  unmap(): void;
  destroy(): void;
}
interface GpuEncoderLike {
  resolveQuerySet(set: unknown, first: number, count: number, dest: GpuBufferLike, offset: number): void;
  copyBufferToBuffer(src: GpuBufferLike, srcOffset: number, dst: GpuBufferLike, dstOffset: number, size: number): void;
  finish(): unknown;
}
interface GpuDeviceLike {
  features: { has(name: string): boolean };
  createQuerySet(d: { type: 'timestamp'; count: number; label?: string }): { destroy(): void };
  createBuffer(d: { size: number; usage: number; label?: string }): GpuBufferLike;
  createCommandEncoder(d?: { label?: string }): GpuEncoderLike;
  queue: { submit(buffers: unknown[]): void };
}
type PassDescriptor = { timestampWrites?: unknown; label?: string };
interface EncoderPrototype {
  beginRenderPass(d: PassDescriptor): unknown;
  beginComputePass(d?: PassDescriptor): unknown;
}

// GPUBufferUsage and GPUMapMode bits, from the WebGPU specification.
const MAP_READ = 0x0001;
const COPY_SRC = 0x0004;
const COPY_DST = 0x0008;
const QUERY_RESOLVE = 0x0200;
const MAP_MODE_READ = 0x0001;

/** The most passes timed in one frame; more go untimed and the frame is not counted. */
const MAX_PASSES = 256;
const READBACKS = 6;

/**
 * A pass's name, from the label Babylon gives its descriptor: a render
 * target's pass (`[frame|n] - <target> - RenderPass`) is named for the
 * target, the main pass is `main`, and the texture manager's own passes
 * (`BabylonWebGPUDevice<n>_<what>_...`) for what they do, so every mip level
 * and face of one job adds up under one name. No label takes `fallback`.
 */
export function passName(label: string | undefined, fallback: string): string {
  if (!label) return fallback;
  const target = /^\[\d+\|\d+\] - (.*) - RenderPass$/.exec(label);
  if (target) return target[1]!;
  if (/^\[\d+\|\d+\] - MainRenderPass$/.test(label)) return 'main';
  const internal = /^BabylonWebGPUDevice\d+_([A-Za-z0-9]+)/.exec(label);
  if (internal) return internal[1] === 'generateMipmaps' ? 'mipmaps' : internal[1]!;
  return label;
}

export function createPassTimer(engine: AbstractEngine): FrameTimer | null {
  const device = (engine as unknown as { _device?: GpuDeviceLike })._device;
  const Encoder = (globalThis as { GPUCommandEncoder?: { prototype: EncoderPrototype } }).GPUCommandEncoder;
  if (!device || !Encoder || !device.features.has('timestamp-query')) return null;

  const querySet = device.createQuerySet({ type: 'timestamp', count: 2 * MAX_PASSES, label: 'gpuProfile' });
  const resolve = device.createBuffer({ size: 16 * MAX_PASSES, usage: QUERY_RESOLVE | COPY_SRC, label: 'gpuProfileResolve' });
  const free: GpuBufferLike[] = Array.from({ length: READBACKS }, (_, i) => device.createBuffer({ size: 16 * MAX_PASSES, usage: MAP_READ | COPY_DST, label: `gpuProfileRead${i}` }));
  const all = [...free];

  // Each pass is named from its own descriptor as it is encoded: a name carried over from the last
  // render target started would land on whatever pass began next, such as that target's mipmaps.
  let labels: string[] = [];
  let overflow = false;
  let recording = true;
  const writes = (d: PassDescriptor | undefined, fallback: string): PassDescriptor | undefined => {
    if (!recording) return d;
    if (labels.length >= MAX_PASSES) {
      overflow = true;
      return d;
    }
    const i = labels.length;
    labels.push(passName(d?.label, fallback));
    return { ...(d ?? {}), timestampWrites: { querySet, beginningOfPassWriteIndex: 2 * i, endOfPassWriteIndex: 2 * i + 1 } };
  };
  const proto = Encoder.prototype;
  const beginRender = proto.beginRenderPass;
  const beginCompute = proto.beginComputePass;
  proto.beginRenderPass = function (this: unknown, d: PassDescriptor) {
    return beginRender.call(this, writes(d, 'other render pass')!);
  };
  proto.beginComputePass = function (this: unknown, d?: PassDescriptor) {
    return beginCompute.call(this, writes(d, 'compute'));
  };

  let collecting: StepSample | null = null;
  let passesSeen = 0;
  let passesZero = 0;
  let smallestNs = Infinity;
  let framesDrawn = 0;
  let framesTimed = 0;
  let postProcessed = false;
  let disposed = false;
  // After the frame's command buffers are submitted: resolve its timestamps and read them back without waiting on them.
  const observer = engine.onEndFrameObservable.add(() => {
    if (collecting) framesDrawn++;
    const count = labels.length;
    const frameLabels = labels;
    const whole = !overflow;
    // The window this frame was drawn in: a frame read back after its window closed counts in none.
    const target = collecting;
    labels = [];
    overflow = false;
    if (count > 0) {
      const buffer = free.pop()!;
      const encoder = device.createCommandEncoder({ label: 'gpuProfileResolve' });
      encoder.resolveQuerySet(querySet, 0, 2 * count, resolve, 0);
      encoder.copyBufferToBuffer(resolve, 0, buffer, 0, 16 * count);
      device.queue.submit([encoder.finish()]);
      buffer.mapAsync(MAP_MODE_READ).then(
        () => {
          if (disposed) return;
          const t = new BigUint64Array(buffer.getMappedRange(0, 16 * count).slice(0));
          buffer.unmap();
          free.push(buffer);
          if (!whole || !target || target !== collecting) return;
          let frameNs = 0;
          const perLabel = new Map<string, number>();
          for (let i = 0; i < count; i++) {
            const begin = t[2 * i]!, end = t[2 * i + 1]!;
            // A pass whose timestamps were never written (its commands not yet submitted) reads 0: left out.
            if (begin === 0n || end < begin) continue;
            const ns = Number(end - begin);
            passesSeen++;
            if (ns === 0) passesZero++;
            else smallestNs = Math.min(smallestNs, ns);
            frameNs += ns;
            const label = frameLabels[i]!;
            if (label.startsWith('PostProcessRTT')) postProcessed = true;
            perLabel.set(label, (perLabel.get(label) ?? 0) + ns);
          }
          framesTimed++;
          target.frameMs.push(frameNs / 1e6);
          for (const [label, ns] of perLabel) (target.passMs[label] ??= []).push(ns / 1e6);
        },
        () => free.push(buffer),
      );
    }
    // The next frame is timed only if a readback buffer is free for it.
    recording = free.length > 0;
  });

  return {
    kind: 'gpu-timestamps',
    note() {
      if (passesSeen === 0) return 'no pass was timed';
      const zero = Math.round((100 * passesZero) / passesSeen);
      const finest = Number.isFinite(smallestNs) ? `${(smallestNs / 1e6).toFixed(3)} ms` : 'n/a';
      const rounded = zero >= 20 || smallestNs >= 50_000;
      const notes = [
        rounded
          ? `timestamps look rounded (${zero}% of passes read 0, finest ${finest}); chrome://flags/#enable-webgpu-developer-features gives full precision`
          : `finest pass ${finest}, ${zero}% of passes read 0`,
        `${framesTimed} of ${framesDrawn} frames timed while sampling`,
        'pass times are means',
      ];
      // With post-processing on, the scene is drawn into the first post-process's target, and `main` is only the last copy to the screen.
      if (postProcessed) notes.push('the scene itself draws into the first PostProcessRTT; main is the final copy to the screen');
      return notes.join('; ');
    },
    start() {
      collecting = { frameMs: [], passMs: {} };
    },
    stop() {
      const s = collecting ?? { frameMs: [], passMs: {} };
      collecting = null;
      return s;
    },
    dispose() {
      disposed = true;
      engine.onEndFrameObservable.remove(observer);
      proto.beginRenderPass = beginRender;
      proto.beginComputePass = beginCompute;
      querySet.destroy();
      resolve.destroy();
      for (const b of all) b.destroy();
    },
  };
}

// --- WebGL2: a timer query around each frame -----------------------------

/**
 * EXT_disjoint_timer_query_webgl2 read directly rather than through Babylon's
 * query extension, which would pull more of the engine into shared chunks,
 * and which keeps only one frame in flight. Here a few are in flight, so
 * most frames are timed; a frame the driver marks disjoint is dropped.
 */
function createGlTimer(engine: AbstractEngine): FrameTimer | null {
  const gl = (engine as unknown as { _gl?: WebGL2RenderingContext })._gl;
  const ext = gl?.getExtension('EXT_disjoint_timer_query_webgl2') as { TIME_ELAPSED_EXT: number; GPU_DISJOINT_EXT: number } | null | undefined;
  if (!gl || !ext) return null;
  let collecting: StepSample | null = null;
  let active: WebGLQuery | null = null;
  const pending: Array<{ query: WebGLQuery; collect: boolean }> = [];
  let framesDrawn = 0;
  let framesTimed = 0;
  const begin = engine.onBeginFrameObservable.add(() => {
    if (active || pending.length >= 8) return;
    active = gl.createQuery();
    if (active) gl.beginQuery(ext.TIME_ELAPSED_EXT, active);
  });
  const end = engine.onEndFrameObservable.add(() => {
    if (collecting) framesDrawn++;
    if (active) {
      gl.endQuery(ext.TIME_ELAPSED_EXT);
      pending.push({ query: active, collect: collecting !== null });
      active = null;
    }
    const disjoint = gl.getParameter(ext.GPU_DISJOINT_EXT) as boolean;
    while (pending.length && gl.getQueryParameter(pending[0]!.query, gl.QUERY_RESULT_AVAILABLE)) {
      const { query, collect } = pending.shift()!;
      const ns = gl.getQueryParameter(query, gl.QUERY_RESULT) as number;
      gl.deleteQuery(query);
      if (!disjoint && collect && collecting) {
        collecting.frameMs.push(ns / 1e6);
        framesTimed++;
      }
    }
  });
  return {
    kind: 'webgl-timer-query',
    // WebGL sends its commands as the frame is built, so the query also counts the GPU waiting on them.
    note: () => `${framesTimed} of ${framesDrawn} frames timed while sampling; includes time the GPU waits on the CPU's commands`,
    start() {
      collecting = { frameMs: [], passMs: {} };
    },
    stop() {
      const s = collecting ?? { frameMs: [], passMs: {} };
      collecting = null;
      return s;
    },
    dispose() {
      engine.onBeginFrameObservable.remove(begin);
      engine.onEndFrameObservable.remove(end);
      if (active) gl.endQuery(ext.TIME_ELAPSED_EXT);
      for (const p of pending) gl.deleteQuery(p.query);
      if (active) gl.deleteQuery(active);
    },
  };
}

// --- Without a GPU timer: the CPU's frame interval ----------------------

function createIntervalTimer(engine: AbstractEngine): FrameTimer {
  let collecting: StepSample | null = null;
  const observer: Observer<AbstractEngine> = engine.onEndFrameObservable.add(() => {
    collecting?.frameMs.push(engine.getDeltaTime());
  });
  return {
    kind: 'cpu-frame-interval',
    note: () => '',
    start() {
      collecting = { frameMs: [], passMs: {} };
    },
    stop() {
      const s = collecting ?? { frameMs: [], passMs: {} };
      collecting = null;
      return s;
    },
    dispose() {
      engine.onEndFrameObservable.remove(observer);
    },
  };
}

function createTimer(engine: AbstractEngine, kind: string): FrameTimer {
  return (kind === 'webgpu' ? createPassTimer(engine) : createGlTimer(engine)) ?? createIntervalTimer(engine);
}

// --- The profiler's own toggles, for effects with no live hint ----------

/**
 * Each toggle, while off, is held off every frame, because the planet view
 * may make the thing again (a cloud layer is drawn anew when its mode
 * changes). Turned back on, it gives back exactly what it turned off.
 */
function createToggles(scene: () => Scene) {
  const hiddenMeshes = (name: string) => {
    const hidden = new Set<{ setEnabled(on: boolean): void; isEnabled(): boolean; isDisposed(): boolean }>();
    return {
      hold() {
        for (const m of scene().meshes) {
          if (m.name !== name || !m.isEnabled() || hidden.has(m)) continue;
          m.setEnabled(false);
          hidden.add(m);
        }
      },
      release() {
        for (const m of hidden) if (!m.isDisposed()) m.setEnabled(true);
        hidden.clear();
      },
    };
  };
  const pausedDepth = () => {
    const paused = new Set<{ enabled: boolean }>();
    return {
      hold() {
        const renderers = (scene() as unknown as { _depthRenderer?: Record<string, { enabled: boolean }> })._depthRenderer ?? {};
        for (const r of Object.values(renderers)) {
          if (!r.enabled || paused.has(r)) continue;
          r.enabled = false;
          paused.add(r);
        }
      },
      release() {
        for (const r of paused) r.enabled = true;
        paused.clear();
      },
    };
  };
  // The planet's sky fill, which the blocks' light draws, held off on every material that has it.
  const skyFillHeld = () => {
    const held = new Set<{ skyFillHeld: boolean }>();
    return {
      hold() {
        for (const m of scene().materials) {
          const p = m.pluginManager?.getPlugin('BlockLight') as { skyFillHeld?: boolean } | null | undefined;
          if (!p || p.skyFillHeld !== false) continue;
          p.skyFillHeld = true;
          held.add(p as { skyFillHeld: boolean });
        }
      },
      release() {
        for (const p of held) p.skyFillHeld = false;
        held.clear();
      },
    };
  };
  // The water's mirror of what stands over it, held off on every water material that traces it.
  const mirrorHeld = () => {
    const held = new Set<{ mirrorHeld: boolean }>();
    return {
      hold() {
        for (const m of scene().materials) {
          const p = m.pluginManager?.getPlugin('WaterReflect') as { mirrorHeld?: boolean } | null | undefined;
          if (!p || p.mirrorHeld !== false) continue;
          p.mirrorHeld = true;
          held.add(p as { mirrorHeld: boolean });
        }
      },
      release() {
        for (const p of held) p.mirrorHeld = false;
        held.clear();
      },
    };
  };
  const toggles: Record<string, { hold(): void; release(): void }> = {
    'cloud-meshes': hiddenMeshes('clouds'),
    'sky-dome': hiddenMeshes('atmosphere'),
    'water-depth': pausedDepth(),
    'water-mirror': mirrorHeld(),
    'sky-fill': skyFillHeld(),
  };
  const off = new Set<string>();
  let observed: { scene: Scene; observer: Observer<Scene> } | undefined;
  const holdAll = () => {
    for (const id of off) toggles[id]?.hold();
  };
  return {
    set(id: string, isOff: boolean) {
      const t = toggles[id];
      if (!t) return;
      if (isOff) {
        off.add(id);
        t.hold();
        const s = scene();
        if (!observed || observed.scene !== s) {
          observed?.scene.onBeforeRenderObservable.remove(observed.observer);
          observed = { scene: s, observer: s.onBeforeRenderObservable.add(holdAll) };
        }
      } else {
        off.delete(id);
        t.release();
        if (off.size === 0 && observed) {
          observed.scene.onBeforeRenderObservable.remove(observed.observer);
          observed = undefined;
        }
      }
    },
    releaseAll() {
      for (const id of [...off]) this.set(id, false);
    },
    stillOff: () => [...off],
  };
}

// --- The overlay ---------------------------------------------------------

const PANEL_CSS =
  'position:fixed;top:8px;right:8px;z-index:40;max-width:min(760px,calc(100vw - 16px));max-height:calc(100vh - 16px);overflow:auto;' +
  'padding:8px 10px;background:rgba(0,0,0,0.82);color:#dfe;border-radius:4px;font:12px/1.45 ui-monospace,Consolas,monospace;';
const BUTTON_CSS = 'margin:0 6px 6px 0;padding:2px 10px;font:inherit;cursor:pointer;';

const wait = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

async function adapterText(engine: AbstractEngine, kind: string): Promise<string> {
  const describe = (i: { vendor?: string; architecture?: string; device?: string; description?: string } | undefined) =>
    i ? [i.vendor, i.architecture, i.device, i.description ? `(${i.description})` : ''].filter(Boolean).join(' ') || 'n/a' : 'n/a';
  if (kind === 'webgpu') {
    const own = (engine as unknown as { _adapterInfo?: Parameters<typeof describe>[0] })._adapterInfo;
    if (own) return describe(own);
    try {
      const nav = navigator as Navigator & { gpu?: { requestAdapter(): Promise<{ info?: Parameters<typeof describe>[0] } | null> } };
      return describe((await nav.gpu?.requestAdapter())?.info);
    } catch {
      return 'n/a';
    }
  }
  const info = (engine as unknown as { getGlInfo?(): { vendor?: string; renderer?: string } }).getGlInfo?.();
  return info ? `${info.vendor ?? ''} ${info.renderer ?? ''}`.trim() || 'n/a' : 'n/a';
}

export function startGpuProfile(o: GpuProfileOptions): { dispose(): void } {
  const { engine } = o;
  const timer = createTimer(engine, o.kind);
  const toggles = createToggles(o.scene);

  const panel = document.createElement('div');
  panel.setAttribute('data-webverse-gpu-profile', 'waiting');
  panel.style.cssText = PANEL_CSS;
  const buttons = document.createElement('div');
  const runButton = document.createElement('button');
  runButton.textContent = 'Run now';
  const copyButton = document.createElement('button');
  copyButton.textContent = 'Copy';
  copyButton.disabled = true;
  const closeButton = document.createElement('button');
  closeButton.textContent = 'Close';
  for (const b of [runButton, copyButton, closeButton]) {
    b.type = 'button';
    b.style.cssText = BUTTON_CSS;
    buttons.appendChild(b);
  }
  const status = document.createElement('div');
  const out = document.createElement('pre');
  out.style.cssText = 'margin:6px 0 0;white-space:pre-wrap;';
  panel.append(buttons, status, out);
  document.body.appendChild(panel);

  let running = false;
  let stopped = false;
  let text = '';
  const setStatus = (s: string) => {
    status.textContent = s;
  };

  const run = async () => {
    if (running || stopped) return;
    running = true;
    runButton.disabled = true;
    panel.setAttribute('data-webverse-gpu-profile', 'running');
    const hints = o.hints();
    const camera = o.scene().activeCamera;
    const startPos = camera?.globalPosition.clone();
    const startDir = camera?.getDirection(Vector3.Forward());
    const before = hintsBefore(SWEEP_STEPS, (name) => hints.get(name));
    try {
      const results = await runSweep(SWEEP_STEPS, {
        getHint: (name: HintName) => hints.get(name),
        setHint: (name: HintName, value: string) => hints.set(name, value),
        setToggle: (id, off) => toggles.set(id, off),
        settle: (ms) => wait(ms),
        sample: async (ms) => {
          timer.start();
          await wait(ms);
          // The last frames' timestamps are still being read back.
          await wait(100);
          return timer.stop();
        },
        onStep: (i, step) => setStatus(`Hold the camera still. Step ${i + 1} of ${SWEEP_STEPS.length}: ${step.label}`),
        shouldStop: () => stopped,
      });
      if (stopped) return;
      // Each step's passes, for a harness that compares one pass across steps (the readout gives the baseline's only).
      console.info(`[gpu-profile] steps ${JSON.stringify(results.map((r) => ({ id: r.step.id, frames: r.frames, frameMs: r.frameMs, passMs: r.passMs })))}`);
      const now = o.scene().activeCamera;
      const endDir = now?.getDirection(Vector3.Forward());
      const moved = !!(startPos && now && (now.globalPosition.subtract(startPos).length() > 0.05 || (startDir && endDir && startDir.dot(endDir) < 0.9999)));
      const canvas = engine.getRenderingCanvas();
      const rect = canvas?.getBoundingClientRect();
      const info: ReadoutInfo = {
        engine: o.kind,
        adapter: await adapterText(engine, o.kind),
        tier: o.tier(),
        canvas: { width: engine.getRenderWidth(), height: engine.getRenderHeight(), cssWidth: Math.round(rect?.width ?? 0), cssHeight: Math.round(rect?.height ?? 0) },
        dpr: window.devicePixelRatio,
        renderScale: o.renderScale(),
        timer: timer.kind,
        timerNote: timer.note(),
        cameraMoved: moved,
        // Read back from the store itself, so the readout says what is so rather than what the sweep meant to do.
        notGivenBack: [...hintsNotGivenBack(before, (name) => hints.get(name)), ...toggles.stillOff().map((id) => `${id} still off`)],
        when: new Date().toISOString(),
      };
      text = formatReadout(info, summarise(results));
      out.textContent = text;
      copyButton.disabled = false;
      setStatus(info.notGivenBack.length ? 'Done, but not everything is back: see the readout.' : 'Done. Every effect is back as the world set it.');
      panel.setAttribute('data-webverse-gpu-profile', 'done');
      console.log(text);
    } catch (err) {
      setStatus(`The sweep stopped: ${String(err)}`);
      panel.setAttribute('data-webverse-gpu-profile', 'error');
    } finally {
      toggles.releaseAll();
      running = false;
      runButton.disabled = false;
      runButton.textContent = 'Run again';
    }
  };

  runButton.addEventListener('click', () => void run());
  copyButton.addEventListener('click', () => {
    const fallback = () => {
      const area = document.createElement('textarea');
      area.value = text;
      document.body.appendChild(area);
      area.select();
      document.execCommand('copy');
      area.remove();
    };
    const done = () => setStatus('Copied.');
    if (navigator.clipboard?.writeText) navigator.clipboard.writeText(text).then(done, () => (fallback(), done()));
    else (fallback(), done());
  });
  closeButton.addEventListener('click', () => dispose());

  // Starts by itself once the world has been in for a while and its meshes have stopped coming,
  // so the sweep measures one scene and not the planet's blocks arriving.
  const started = performance.now();
  let enteredAt: number | undefined;
  let meshCount = -1;
  let meshesChangedAt = 0;
  const tick = setInterval(() => {
    if (running || stopped || panel.getAttribute('data-webverse-gpu-profile') !== 'waiting') return;
    const now = performance.now();
    if (!o.worldEntered()) {
      setStatus(`Waiting for the world (${Math.round((now - started) / 1000)} s). Timer: ${timer.kind}.`);
      return;
    }
    enteredAt ??= now;
    const count = o.scene().meshes.length;
    if (count !== meshCount) {
      meshCount = count;
      meshesChangedAt = now;
    }
    const left = Math.min(Math.max(AUTO_START_MS - (now - enteredAt), MESHES_STILL_MS - (now - meshesChangedAt)), AUTO_START_LIMIT_MS - (now - enteredAt));
    if (left > 0) setStatus(`The sweep starts in ${Math.ceil(left / 1000)} s, once the world has stopped loading; hold the camera still. Timer: ${timer.kind}.`);
    else void run();
  }, 250);

  let disposed = false;
  const dispose = () => {
    if (disposed) return;
    disposed = true;
    stopped = true;
    clearInterval(tick);
    toggles.releaseAll();
    timer.dispose();
    panel.remove();
  };
  return { dispose };
}
