/**
 * The GPU profile's sweep: what each of a planet's effects costs a frame,
 * found by turning it off, letting the frame settle, timing it, and turning
 * it back on. Most effects are turned off through the world's own client
 * hints, the store a script's `ClientHints.Set` writes to; the few with no
 * hint that can be changed while the planet runs go through the profiler's
 * own toggles (see src/debug/gpuProfile.ts). Each hint is given back the
 * value the world had before the sweep, after its step and again at the end,
 * whatever happens in between.
 *
 * Pure: no Babylon and no DOM, so the order, the giving back, the arithmetic
 * and the readout are tested without a browser.
 */

import type { HintName } from '../veml/clientHintsVocabulary';

export interface SweepStep {
  id: string;
  /** How the readout names it. */
  label: string;
  /** The hints this step sets, and the value that turns the effect off. */
  hints: Array<[HintName, string]>;
  /** The profiler's own toggles this step turns off, by id. */
  toggles: string[];
}

const hint = (id: string, label: string, name: HintName, off: string): SweepStep => ({ id, label: `${label}  ${name}=${off}`, hints: [[name, off]], toggles: [] });
const toggle = (id: string, label: string): SweepStep => ({ id, label, hints: [], toggles: [id] });
const BASELINE: SweepStep = { id: 'baseline', label: 'baseline', hints: [], toggles: [] };

const EFFECTS: SweepStep[] = [
  hint('clouds', 'clouds', 'planet.clouds', 'none'),
  hint('cloud-volume', 'cloud volume', 'planet.cloud-volume', 'off'),
  // `planet.clouds="none"` leaves the layers drawn, covering nothing: hiding them shows what drawing them costs.
  toggle('cloud-meshes', 'cloud layers hidden (profiler)'),
  // `planet.air` is read once, when the planet is made, so the sky dome is hidden instead.
  toggle('sky-dome', 'sky dome hidden (profiler)'),
  hint('fog', 'fog', 'planet.fog', 'none'),
  hint('haze', 'haze', 'planet.haze', 'none'),
  hint('sun-shadows', 'sun shadows', 'planet.sun-shadows', 'off'),
  hint('water-reflections', 'water reflections', 'planet.water-reflections', 'none'),
  // The water's depth map has no hint: the profiler stops drawing it.
  toggle('water-depth', 'water depth map paused (profiler)'),
  // The water's mirror of what stands over it, held off in the water's shader.
  toggle('water-mirror', 'water mirror held off (profiler)'),
  hint('sun-flare', 'sun flare', 'planet.sun-flare', 'none'),
  hint('bloom', 'bloom', 'planet.bloom', 'none'),
  hint('sway', 'sway', 'planet.sway', 'none'),
  hint('waves', 'waves', 'planet.waves', 'none'),
  hint('stars', 'stars', 'planet.stars', 'none'),
  // The sky's fill light, turned and coloured, held off on the ground's materials.
  toggle('sky-fill', 'sky fill held off (profiler)'),
  hint('block-relief', 'block relief', 'planet.block-relief', 'none'),
];

/** The baseline, each effect off in turn, all of them off at once, and the baseline again to show drift. */
export const SWEEP_STEPS: readonly SweepStep[] = [
  BASELINE,
  ...EFFECTS,
  { id: 'all', label: 'everything above at once', hints: EFFECTS.flatMap((s) => s.hints), toggles: EFFECTS.flatMap((s) => s.toggles) },
  BASELINE,
];

export const SETTLE_MS = 2000;
export const SAMPLE_MS = 3000;

/** The middle value; NaN for none. */
export function median(values: readonly number[]): number {
  if (values.length === 0) return NaN;
  const s = [...values].sort((a, b) => a - b);
  const mid = s.length >> 1;
  return s.length % 2 ? s[mid]! : (s[mid - 1]! + s[mid]!) / 2;
}

/** The mean; NaN for none. */
export function mean(values: readonly number[]): number {
  return values.length === 0 ? NaN : values.reduce((a, b) => a + b, 0) / values.length;
}

/** What one sampling window saw: each frame's time, and each pass's time in each frame it ran, in ms. */
export interface StepSample {
  frameMs: number[];
  passMs: Record<string, number[]>;
}

export interface SweepDeps {
  getHint(name: HintName): string | null;
  setHint(name: HintName, value: string): boolean;
  setToggle(id: string, off: boolean): void;
  settle(ms: number): Promise<void>;
  sample(ms: number): Promise<StepSample>;
  /** Told as each step starts. */
  onStep?(index: number, step: SweepStep): void;
  /** Checked before each step: true ends the sweep there. */
  shouldStop?(): boolean;
}

export interface StepResult {
  step: SweepStep;
  frames: number;
  /** The median frame. */
  frameMs: number;
  /**
   * Each pass's mean. A mean, not a median: Chrome rounds timestamps to a
   * tenth of a millisecond, so one short pass reads 0 or 0.1 frame by frame,
   * and only the mean comes out near its true time.
   */
  passMs: Record<string, number>;
}

export async function runSweep(steps: readonly SweepStep[], deps: SweepDeps, timing: { settleMs: number; sampleMs: number } = { settleMs: SETTLE_MS, sampleMs: SAMPLE_MS }): Promise<StepResult[]> {
  // The world's own value of every hint the sweep touches, read before it touches any.
  const world = new Map<HintName, string>();
  for (const step of steps) for (const [name] of step.hints) if (!world.has(name)) world.set(name, deps.getHint(name) ?? 'auto');
  const giveBack = (step: SweepStep) => {
    for (const [name] of step.hints) deps.setHint(name, world.get(name)!);
    for (const id of step.toggles) deps.setToggle(id, false);
  };
  const results: StepResult[] = [];
  try {
    for (const [index, step] of steps.entries()) {
      if (deps.shouldStop?.()) break;
      deps.onStep?.(index, step);
      for (const [name, value] of step.hints) deps.setHint(name, value);
      for (const id of step.toggles) deps.setToggle(id, true);
      try {
        await deps.settle(timing.settleMs);
        const s = await deps.sample(timing.sampleMs);
        const passMs: Record<string, number> = {};
        for (const [label, values] of Object.entries(s.passMs)) passMs[label] = mean(values);
        results.push({ step, frames: s.frameMs.length, frameMs: median(s.frameMs), passMs });
      } finally {
        giveBack(step);
      }
    }
  } finally {
    const all = new Set(steps.flatMap((s) => s.toggles));
    for (const [name, value] of world) deps.setHint(name, value);
    for (const id of all) deps.setToggle(id, false);
  }
  return results;
}

/** The value of every hint the steps touch, read before a sweep, to check against after it. */
export function hintsBefore(steps: readonly SweepStep[], getHint: (name: HintName) => string | null): Map<HintName, string | null> {
  return new Map(steps.flatMap((s) => s.hints.map(([name]) => [name, getHint(name)] as const)));
}

/** Each hint whose value now is not the one it had before, as `name is now, was before`. */
export function hintsNotGivenBack(before: ReadonlyMap<HintName, string | null>, getHint: (name: HintName) => string | null): string[] {
  const out: string[] = [];
  for (const [name, was] of before) {
    const now = getHint(name);
    if (now !== was) out.push(`${name} is ${now}, was ${was}`);
  }
  return out;
}

export interface SweepSummary {
  baselineBefore: number;
  baselineAfter: number;
  /** The mean of the two baselines. */
  baseline: number;
  /** After minus before. */
  drift: number;
  /** The fewest frames any step had. */
  frames: number;
  rows: Array<{ id: string; label: string; offMs: number; savedMs: number; pct: number; frames: number }>;
  /** Each pass at the baseline, the mean of the two, the most costly first. */
  passes: Array<{ label: string; ms: number }>;
}

export function summarise(results: readonly StepResult[]): SweepSummary {
  const baselines = results.filter((r) => r.step.id === 'baseline');
  const before = baselines[0]?.frameMs ?? NaN;
  const after = baselines.length > 1 ? baselines[baselines.length - 1]!.frameMs : before;
  const baseline = (before + after) / 2;
  const labels = [...new Set(baselines.flatMap((b) => Object.keys(b.passMs)))];
  const passes = labels
    .map((label) => ({ label, ms: mean(baselines.map((b) => b.passMs[label] ?? 0)) }))
    .sort((a, b) => b.ms - a.ms);
  return {
    baselineBefore: before,
    baselineAfter: after,
    baseline,
    drift: after - before,
    frames: results.length ? Math.min(...results.map((r) => r.frames)) : 0,
    rows: results
      .filter((r) => r.step.id !== 'baseline')
      .map((r) => ({ id: r.step.id, label: r.step.label, offMs: r.frameMs, savedMs: baseline - r.frameMs, pct: ((baseline - r.frameMs) / baseline) * 100, frames: r.frames })),
    passes,
  };
}

export type TimerKind = 'gpu-timestamps' | 'webgl-timer-query' | 'cpu-frame-interval';

export interface ReadoutInfo {
  engine: string;
  adapter: string;
  tier: string;
  /** The drawing buffer and the canvas's size on the page. */
  canvas: { width: number; height: number; cssWidth: number; cssHeight: number };
  dpr: number;
  renderScale: number;
  timer: TimerKind;
  /** Anything the timer's reader should know, such as its rounding. */
  timerNote: string;
  cameraMoved: boolean;
  /** Each hint not back at the world's value after the sweep (from `hintsNotGivenBack`); empty when all are. */
  notGivenBack: string[];
  when: string;
}

const TIMER_TEXT: Record<TimerKind, string> = {
  'gpu-timestamps': 'GPU timestamps per pass',
  'webgl-timer-query': 'GPU timer query (EXT_disjoint_timer_query_webgl2), whole frame',
  'cpu-frame-interval': 'CPU frame interval (no GPU timer on this device): fps-bound, not GPU time',
};

const ms = (v: number) => (Number.isFinite(v) ? v.toFixed(2) : 'n/a');
const signed = (v: number) => (Number.isFinite(v) ? `${v >= 0 ? '+' : ''}${v.toFixed(2)}` : 'n/a');
const pct = (v: number) => (Number.isFinite(v) ? `${v.toFixed(1)}%` : 'n/a');
const LABEL = 50;

/** The readout as plain text: what the overlay shows, the Copy button copies and the console prints. */
export function formatReadout(info: ReadoutInfo, s: SweepSummary): string {
  const lines = [
    `WebVerse GPU profile, ${info.when}`,
    `engine ${info.engine}, adapter ${info.adapter}`,
    `tier ${info.tier}, canvas ${info.canvas.width}x${info.canvas.height} (css ${info.canvas.cssWidth}x${info.canvas.cssHeight}), dpr ${info.dpr}, render scale ${info.renderScale}`,
    `timer ${TIMER_TEXT[info.timer]}${info.timerNote ? `; ${info.timerNote}` : ''}`,
    `baseline ${ms(s.baseline)} ms (${ms(s.baselineBefore)} before, ${ms(s.baselineAfter)} after, drift ${signed(s.drift)}), at least ${s.frames} frames a step`,
  ];
  lines.push(info.notGivenBack.length ? `NOT given back: ${info.notGivenBack.join(', ')}` : 'every hint the sweep changed is back as the world set it');
  if (info.cameraMoved) lines.push('camera moved during the sweep: the numbers mix two views');
  lines.push('', 'effect'.padEnd(LABEL) + 'on ms'.padStart(8) + 'off ms'.padStart(9) + 'saved'.padStart(8) + '% frame'.padStart(9) + 'frames'.padStart(8));
  for (const r of s.rows) lines.push(r.label.padEnd(LABEL) + ms(s.baseline).padStart(8) + ms(r.offMs).padStart(9) + ms(r.savedMs).padStart(8) + pct(r.pct).padStart(9) + String(r.frames).padStart(8));
  if (s.passes.length) {
    lines.push('', 'pass'.padEnd(LABEL) + 'ms'.padStart(8) + '% frame'.padStart(9));
    for (const p of s.passes) lines.push(p.label.padEnd(LABEL) + ms(p.ms).padStart(8) + pct((p.ms / s.baseline) * 100).padStart(9));
  }
  return lines.join('\n');
}
